static int r8153_set_rx_early_size(struct r8152 *tp)
{
	u32 ocp_data = tp->rx_buf_sz - rx_reserved_size(tp, tp->netdev->mtu);
	int ret;

	switch (tp->version) {
	case RTL_VER_03:
	case RTL_VER_04:
	case RTL_VER_05:
	case RTL_VER_06:
		ret = ocp_write_word(tp, MCU_TYPE_USB, USB_RX_EARLY_SIZE,
				     ocp_data / 4);
		break;
	case RTL_TEST_01:
	case RTL_VER_08:
	case RTL_VER_09:
	case RTL_VER_10:
	case RTL_VER_11:
	case RTL_VER_12:
	case RTL_VER_13:
	case RTL_VER_14:
	case RTL_VER_15:
		ret = ocp_write_word(tp, MCU_TYPE_USB, USB_RX_EARLY_SIZE,
				     ocp_data / 8);
		break;
	case RTL_VER_16:
	case RTL_VER_17:
		ret = ocp_write_word(tp, MCU_TYPE_USB, USB_RX_EARLY_SIZE,
				     ocp_data / 16);
		break;
	default:
		ret = -ENODEV;
		WARN_ON_ONCE(1);
		break;
	}

	return ret;
}
